    internal static void RemoveDetailed(int lod, int[] indices, bool[] removed)
    {
        var data = lod switch
        {
            0 => (Count: 36710, Faces: Level0),
            1 => (Count: 22015, Faces: Level1),
            _ => throw new ArgumentOutOfRangeException(nameof(lod))
        };
        if (indices.Length != data.Count * 3 || removed.Length != data.Count)
            throw new InvalidOperationException("Lift04 detailed road-top layout changed.");
        foreach (var face in data.Faces)
        {
            var offset = face.Triangle * 3;
            if (indices[offset] != face.A || indices[offset + 1] != face.B || indices[offset + 2] != face.C)
                throw new InvalidOperationException("Lift04 detailed road-top topology changed.");
            removed[face.Triangle] = true;
        }
    }

